const E = v => String(v == null ? '' : v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function load(k, d){ try{ const v = JSON.parse(localStorage.getItem(k)); return v == null ? d : v; }catch(e){ return d; } }
function save(k, v){ try{ localStorage.setItem(k, JSON.stringify(v)); }catch(e){} }
function shuffle(a){ a = a.slice(); for(let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
function canSpeak(){ return typeof speechSynthesis !== 'undefined' && typeof SpeechSynthesisUtterance !== 'undefined'; }
function speak(t){ if(!canSpeak()) return; try{ speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(String(t).replace(/^to /, '').replace(/\.\.\./g, '')); u.lang = 'en-GB'; u.rate = 0.9; speechSynthesis.speak(u); }catch(e){} }
function stopSpeak(){ if(canSpeak()) try{ speechSynthesis.cancel(); }catch(e){} }
const CONTR = { "i'm":'i am', "it's":'it is', "he's":'he is', "she's":'she is', "that's":'that is', "don't":'do not', "doesn't":'does not', "can't":'cannot', "won't":'will not', "isn't":'is not', "aren't":'are not', "i'll":'i will', "we'll":'we will', "i've":'i have', "let's":'let us' };
function norm(s, word){
  s = String(s).toLowerCase().replace(/[’‘`]/g, "'");
  Object.keys(CONTR).forEach(k => { s = s.split(k).join(CONTR[k]); });
  s = s.replace(/[.!?,;:"]/g, '').replace(/\s+/g, ' ').trim();
  if(word) s = s.replace(/^to /, '');
  return s;
}
function lev(a, b){ const m = a.length, n = b.length; if(!m) return n; if(!n) return m; let p = []; for(let j = 0; j <= n; j++) p[j] = j; for(let i = 1; i <= m; i++){ const c = [i]; for(let j = 1; j <= n; j++) c[j] = Math.min(p[j] + 1, c[j - 1] + 1, p[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); p = c; } return p[n]; }
function same(inp, ans, word){ const a = norm(inp, word), b = norm(ans, word); if(a === b) return true; if(!word && b.length >= 14 && lev(a, b) <= 1) return true; return false; }

const KEY = 'bp_vocab2';
function P(){ return load(KEY, {}); }
function PT(id){ const p = P()[id] || {}; return { l: !!p.l, t: !!p.t, g: p.g || [0, 0, 0], s: p.s || 0, gd: !!p.gd }; }
function setPT(id, f){ const all = P(), cur = Object.assign({}, all[id] || {}); f(cur); all[id] = cur; save(KEY, all); }
function themeById(id){ return THEMES.find(t => t.id === id); }
function abtOf(id){ return ABT.find(a => a.t.includes(id)); }
function stepOf(id){ const p = PT(id); return !p.l ? 0 : !p.t ? 1 : !p.gd ? 2 : 3; }
function stars(id){ const p = PT(id); return (p.t ? 1 : 0) + (p.gd ? 1 : 0) + (p.s >= 1 ? 1 : 0); }
function wrongBook(){ return load('bp_vocab_wrong2', {}); }
function markWrong(w, bad){ const b = wrongBook(), k = w[0]; if(bad) b[k] = [w[0], w[1], w[2] || '']; else delete b[k]; save('bp_vocab_wrong2', b); }
function pay(n){ if(n <= 0) return 0; try{ if(typeof fruitPay === 'function'){ const r = fruitPay(-n); if(r && r.ok) return n; } }catch(e){} return 0; }
function rnd(a){ return a[Math.floor(Math.random() * a.length)]; }
